import { LevelChip } from "./level-chip";
import type { Presence } from "./presence";
import { FollowPill, PresenceStrip } from "./presence-strip";
import { PALETTE, PENCIL_SIZES } from "./stroke";
import type { SurfaceView, Tool } from "./surface";
import { CONNECTION_LABEL, type Connection } from "./sync";

const DOT_PX = { Small: 4, Medium: 9, Large: 16 } as const;

export type HistoryState = { canUndo: boolean; canRedo: boolean };

type ToolbarProps = {
  tool: Tool;
  onChange: (tool: Tool) => void;
  connection: Connection;
  history: HistoryState;
  onUndo: () => void;
  onRedo: () => void;
  view: SurfaceView;
  onLevel: (level: number) => void;
  shareOpen: boolean;
  onShare: () => void;
  presence: Presence;
  onFollow: (clientId: number | undefined) => void;
};

export function Toolbar({
  tool,
  onChange,
  connection,
  history,
  onUndo,
  onRedo,
  view,
  onLevel,
  shareOpen,
  onShare,
  presence,
  onFollow,
}: ToolbarProps) {
  return (
    <div class="toolbar" role="toolbar" aria-label="Drawing tools">
      <fieldset class="group" aria-label="Pencil size">
        {PENCIL_SIZES.map((size) => (
          <button
            key={size}
            type="button"
            aria-pressed={tool.mode === "Pencil" && tool.size === size}
            aria-label={`${size} pencil`}
            class="tool"
            onClick={() => onChange({ ...tool, size, mode: "Pencil" })}
          >
            <span class="dot" style={{ width: DOT_PX[size], height: DOT_PX[size] }} />
          </button>
        ))}
      </fieldset>
      <fieldset class="group" aria-label="Colour">
        {PALETTE.map((colour, index) => (
          <button
            key={colour}
            type="button"
            aria-pressed={tool.primary === index}
            aria-label={`Colour ${index + 1}`}
            title="Tap for primary, right-click or long-press for secondary"
            class={tool.secondary === index ? "tool swatch secondary" : "tool swatch"}
            style={{ background: colour }}
            onClick={() => onChange({ ...tool, primary: index })}
            onContextMenu={(event) => {
              event.preventDefault();
              onChange({ ...tool, secondary: index });
            }}
          />
        ))}
      </fieldset>
      <button
        type="button"
        class="tool"
        aria-pressed={tool.mode === "Pan"}
        aria-label="Pan tool"
        title="Drag with one finger to move the board"
        onClick={() => onChange({ ...tool, mode: tool.mode === "Pan" ? "Pencil" : "Pan" })}
      >
        <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
          <path
            d="M12 2v20M2 12h20M12 2l-3 3M12 2l3 3M12 22l-3-3M12 22l3-3M2 12l3-3M2 12l3 3M22 12l-3-3M22 12l-3 3"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
          />
        </svg>
      </button>
      <button
        type="button"
        class="tool"
        aria-pressed={tool.mode === "Select"}
        aria-label="Select tool"
        title="Tap a stroke to select it, drag to move it, Delete to remove it"
        onClick={() => onChange({ ...tool, mode: tool.mode === "Select" ? "Pencil" : "Select" })}
      >
        <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
          <path
            d="M5 3l14 8-6 2-3 6-5-16z"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linejoin="round"
          />
        </svg>
      </button>
      <button
        type="button"
        class="tool"
        aria-pressed={tool.mode === "Eraser"}
        aria-label="Eraser"
        title="Tap or drag across a stroke to delete it"
        onClick={() => onChange({ ...tool, mode: tool.mode === "Eraser" ? "Pencil" : "Eraser" })}
      >
        <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
          <path
            d="M16 3l5 5-11 11H5l-3-3L16 3zM9 10l5 5M10 21h11"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linejoin="round"
            stroke-linecap="round"
          />
        </svg>
      </button>
      <button
        type="button"
        class="tool pair"
        aria-label="Swap primary and secondary colour"
        onClick={() => onChange({ ...tool, primary: tool.secondary, secondary: tool.primary })}
      >
        <span class="chip back" style={{ background: PALETTE[tool.secondary] }} />
        <span class="chip front" style={{ background: PALETTE[tool.primary] }} />
      </button>
      <fieldset class="group" aria-label="History">
        <button
          type="button"
          class="tool"
          aria-label="Undo"
          title="Undo your last change (Ctrl+Z)"
          disabled={!history.canUndo}
          onClick={onUndo}
        >
          <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
            <path
              d="M9 14L4 9l5-5M4 9h10a6 6 0 010 12h-3"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>
        </button>
        <button
          type="button"
          class="tool"
          aria-label="Redo"
          title="Redo your last undone change (Ctrl+Shift+Z)"
          disabled={!history.canRedo}
          onClick={onRedo}
        >
          <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
            <path
              d="M15 14l5-5-5-5M20 9H10a6 6 0 000 12h3"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>
        </button>
      </fieldset>
      <button
        type="button"
        class="tool"
        data-share-toggle
        aria-pressed={shareOpen}
        aria-label="Share"
        title="Share the board link, QR code and PIN"
        onClick={onShare}
      >
        <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
          <path
            d="M8.6 10.6l6.8-4M8.6 13.4l6.8 4M18 5a2.5 2.5 0 11-.01 0M6 9.5a2.5 2.5 0 11-.01 0M18 16.5a2.5 2.5 0 11-.01 0"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
          />
        </svg>
      </button>
      <LevelChip level={view.level} contentLevels={view.contentLevels} onPick={onLevel} />
      <span
        class="status"
        data-connection={connection}
        role="status"
        aria-label={CONNECTION_LABEL[connection]}
        title={CONNECTION_LABEL[connection]}
      />
      <PresenceStrip presence={presence} onFollow={onFollow} />
      <FollowPill presence={presence} onStop={() => onFollow(undefined)} />
    </div>
  );
}
import { useEffect, useRef, useState } from "preact/hooks";
import { levelOptions } from "./level";

type LevelChipProps = {
  level: number;
  contentLevels: readonly number[];
  onPick: (level: number) => void;
};

export function LevelChip({ level, contentLevels, onPick }: LevelChipProps) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const currentRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!open) return;
    currentRef.current?.scrollIntoView({ block: "nearest" });
    const close = (event: PointerEvent) => {
      if (event.target instanceof Node && rootRef.current?.contains(event.target)) return;
      setOpen(false);
    };
    window.addEventListener("pointerdown", close);
    return () => window.removeEventListener("pointerdown", close);
  }, [open]);

  return (
    <div class="level" ref={rootRef}>
      <button
        type="button"
        class="level-chip"
        aria-label={`Zoom level ${level}`}
        aria-expanded={open}
        aria-haspopup="listbox"
        title="Zoom level: 0 is the starting zoom, negative is zoomed in"
        onClick={() => setOpen(!open)}
      >
        {level}
      </button>
      {open && (
        <div class="level-list" role="listbox" aria-label="Zoom levels">
          {levelOptions(level, contentLevels).map((option) => (
            <button
              key={option.level}
              ref={option.current ? currentRef : null}
              type="button"
              role="option"
              aria-selected={option.current}
              aria-label={`Level ${option.level}${option.hasContent ? ", has strokes" : ""}`}
              class="level-option"
              onClick={() => {
                setOpen(false);
                onPick(option.level);
              }}
            >
              <span>{option.level}</span>
              {option.hasContent && <span class="level-dot" aria-hidden="true" />}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
import { useEffect, useRef, useState } from "preact/hooks";
import type { Peer, Presence } from "./presence";

export const MAX_CHIPS = 5;

type PresenceStripProps = {
  presence: Presence;
  onFollow: (clientId: number | undefined) => void;
};

const initial = (name: string): string => (name.trim()[0] ?? "?").toUpperCase();

const chipTitle = (peer: Peer, following: boolean): string => {
  if (peer.self) return "You";
  return following ? `Following ${peer.name}, tap to stop` : `${peer.name}, tap to follow`;
};

function PeerChip({
  peer,
  following,
  onFollow,
}: {
  peer: Peer;
  following: boolean;
  onFollow: (clientId: number | undefined) => void;
}) {
  return (
    <button
      type="button"
      class="peer"
      data-peer={peer.clientId}
      aria-pressed={following}
      aria-label={chipTitle(peer, following)}
      title={chipTitle(peer, following)}
      disabled={peer.self}
      style={{ background: peer.colour }}
      onClick={() => onFollow(following ? undefined : peer.clientId)}
    >
      {initial(peer.name)}
    </button>
  );
}

export function PresenceStrip({ presence, onFollow }: PresenceStripProps) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLFieldSetElement>(null);
  const { peers, following } = presence;
  const shown = peers.length > MAX_CHIPS ? peers.slice(0, MAX_CHIPS - 1) : peers;
  const hidden = peers.slice(shown.length);

  useEffect(() => {
    if (!open) return;
    const close = (event: PointerEvent) => {
      if (event.target instanceof Node && rootRef.current?.contains(event.target)) return;
      setOpen(false);
    };
    window.addEventListener("pointerdown", close);
    return () => window.removeEventListener("pointerdown", close);
  }, [open]);

  if (peers.length === 0) return null;

  return (
    <fieldset class="presence" ref={rootRef} aria-label="People on this board">
      {shown.map((peer) => (
        <PeerChip
          key={peer.clientId}
          peer={peer}
          following={peer.clientId === following}
          onFollow={onFollow}
        />
      ))}
      {hidden.length > 0 && (
        <button
          type="button"
          class="peer more"
          aria-expanded={open}
          aria-haspopup="listbox"
          aria-label={`${hidden.length} more people`}
          title={`${hidden.length} more people`}
          onClick={() => setOpen(!open)}
        >
          +{hidden.length}
        </button>
      )}
      {open && (
        <div class="peer-list" role="listbox" aria-label="More people">
          {hidden.map((peer) => (
            <button
              key={peer.clientId}
              type="button"
              role="option"
              class="peer-option"
              aria-selected={peer.clientId === following}
              disabled={peer.self}
              onClick={() => {
                setOpen(false);
                onFollow(peer.clientId === following ? undefined : peer.clientId);
              }}
            >
              <span class="peer small" style={{ background: peer.colour }} aria-hidden="true">
                {initial(peer.name)}
              </span>
              <span>{peer.name}</span>
            </button>
          ))}
        </div>
      )}
    </fieldset>
  );
}

export function FollowPill({ presence, onStop }: { presence: Presence; onStop: () => void }) {
  const target = presence.peers.find((peer) => peer.clientId === presence.following);
  if (!target) return null;
  return (
    <button type="button" class="follow-pill" onClick={onStop}>
      <span class="peer small" style={{ background: target.colour }} aria-hidden="true">
        {initial(target.name)}
      </span>
      Following {target.name}, tap to stop
    </button>
  );
}
