import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { extname, join } from "node:path";
import { chromium } from "playwright";
import { accessHeaders } from "../npm-scripts/env.mjs";

const [target, label = "live"] = process.argv.slice(2);
const local = !target.startsWith("https://");
const DIR = join(homedir(), "development", ".tmp", "stallion-toolbar", label);
mkdirSync(DIR, { recursive: true });
const GUTTER = 16;
const id = () => {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  let v = 0n;
  for (const b of bytes) v = (v << 8n) | BigInt(b);
  return v.toString(36).padStart(25, "0");
};
const origin = local ? "http://localhost:4999" : target;
const boardUrl = `${origin}/b/${id()}`;
const TYPES = { ".js": "text/javascript", ".css": "text/css", ".html": "text/html", ".png": "image/png", ".webmanifest": "application/manifest+json", ".svg": "image/svg+xml" };

const failures = [];
const expect = (ok, what) => {
  if (!ok) failures.push(what);
  console.log(`${ok ? "ok  " : "FAIL"} ${what}`);
};
const errors = [];

const newContext = async (browser, options) => {
  const context = await browser.newContext({ ...options, extraHTTPHeaders: local ? {} : accessHeaders(), serviceWorkers: "block" });
  if (local) {
    await context.route(`${origin}/**`, (route) => {
      const path = new URL(route.request().url()).pathname;
      const file = join(target, path);
      const hit = path !== "/" && existsSync(file) && extname(file);
      const body = readFileSync(hit ? file : join(target, "index.html"));
      return route.fulfill({ body, contentType: TYPES[extname(hit ? file : "x.html")] ?? "application/octet-stream" });
    });
  }
  return context;
};

const watch = (page, name) => {
  page.on("console", (m) => {
    if (m.type() === "error" && !/favicon/.test(`${m.text()} ${m.location().url}`)) errors.push(`${name}: ${m.text()}`);
  });
  page.on("pageerror", (e) => errors.push(`${name}: ${e.message}`));
};

const open = async (page) => {
  await page.goto(boardUrl, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 20000 });
  await page.waitForTimeout(1500);
};

const box = (page, selector) => page.locator(selector).first().boundingBox();
const inside = (b, vp, gutter) =>
  b && b.x >= gutter - 0.5 && b.y >= -0.5 && b.x + b.width <= vp.width - gutter + 0.5 && b.y + b.height <= vp.height + 0.5;
const overlap = (a, b) => a && b && a.x < b.x + b.width && b.x < a.x + a.width && a.y < b.y + b.height && b.y < a.y + a.height;
const oneLine = (page) =>
  page.evaluate(() => {
    const rows = [...document.querySelectorAll(".toolbar .toolbar-row")];
    return rows.map((row) => new Set([...row.children].map((c) => Math.round(c.getBoundingClientRect().top + c.getBoundingClientRect().height / 2))).size);
  });

const draw = async (page, touch, vp) => {
  const pts = Array.from({ length: 20 }, (_, i) => ({ x: vp.width * 0.3 + (i / 19) * vp.width * 0.4, y: vp.height * 0.55 + Math.sin((i / 19) * Math.PI * 2) * 40 }));
  const clip = { x: vp.width * 0.3 - 20, y: vp.height * 0.55 - 60, width: vp.width * 0.4 + 40, height: 120 };
  const before = await page.screenshot({ clip });
  if (touch) {
    const cdp = await page.context().newCDPSession(page);
    const send = (type, p) => cdp.send("Input.dispatchTouchEvent", { type, touchPoints: p ? [{ x: p.x, y: p.y, id: 1, radiusX: 2, radiusY: 2 }] : [] });
    await send("touchStart", pts[0]);
    for (const p of pts.slice(1)) await send("touchMove", p);
    await send("touchEnd");
    await cdp.detach();
  } else {
    await page.mouse.move(pts[0].x, pts[0].y);
    await page.mouse.down();
    for (const p of pts.slice(1)) await page.mouse.move(p.x, p.y);
    await page.mouse.up();
  }
  await page.waitForTimeout(800);
  const after = await page.screenshot({ clip });
  return !before.equals(after);
};

const checkBar = async (page, vp, name, state) => {
  const bar = await box(page, ".toolbar");
  expect(inside(bar, vp, GUTTER), `${name} ${state}: toolbar ${JSON.stringify(bar)} inside ${vp.width}x${vp.height} with ${GUTTER}px gutters`);
  const lines = await oneLine(page);
  expect(lines.every((n) => n === 1), `${name} ${state}: no row wraps (${JSON.stringify(lines)})`);
  const floater = await box(page, ".presence-floater");
  if (floater) {
    expect(inside(floater, vp, GUTTER), `${name} ${state}: presence floater ${JSON.stringify(floater)} inside the viewport`);
    expect(!overlap(floater, bar), `${name} ${state}: presence floater does not overlap the toolbar`);
  } else expect(!local, `${name} ${state}: presence floater rendered`);
  return lines.length;
};

const browser = await chromium.launch({ headless: true });
const helpers = [];
try {
  const VIEWPORTS = [
    { name: "phone", viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 3 },
    { name: "tablet", viewport: { width: 800, height: 1280 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 },
    { name: "desktop", viewport: { width: 1440, height: 900 }, hasTouch: false, isMobile: false, deviceScaleFactor: 1 },
  ];
  if (!local) {
    for (let i = 0; i < 5; i++) {
      const ctx = await newContext(browser, { viewport: { width: 600, height: 400 } });
      const p = await ctx.newPage();
      await open(p);
      helpers.push(ctx);
    }
  }
  for (const { name, ...options } of VIEWPORTS) {
    const context = await newContext(browser, options);
    const page = await context.newPage();
    watch(page, name);
    await open(page);
    const vp = options.viewport;
    const wide = vp.width >= 900;
    const rows = await checkBar(page, vp, name, wide ? "wide" : "collapsed");
    expect(rows === 1, `${name}: one row (${rows})`);
    expect((await page.locator(".toolbar .expand").count()) === (wide ? 0 : 1), `${name}: expand toggle ${wide ? "absent" : "present"}`);
    const small = await page.locator(".toolbar button, .toolbar .status").evaluateAll((els) => els.filter((e) => e.classList.contains("tool") || e.classList.contains("level-chip")).map((e) => e.getBoundingClientRect()).filter((r) => r.width < 44 || r.height < 44).length);
    expect(small === 0, `${name}: every tool is a 44px target (${small} smaller)`);
    await page.screenshot({ path: join(DIR, `${name}-${wide ? "wide" : "collapsed"}.png`) });
    if (!wide) {
      await page.locator(".toolbar .expand").click();
      await page.waitForTimeout(300);
      const expandedRows = await checkBar(page, vp, name, "expanded");
      expect(expandedRows <= 3 && expandedRows > 1, `${name}: expanded has ${expandedRows} rows`);
      await page.screenshot({ path: join(DIR, `${name}-expanded.png`) });
      await page.getByRole("button", { name: "Colour 3", exact: true }).click();
      await page.waitForTimeout(200);
      expect((await page.locator(".toolbar .toolbar-row").count()) === 1, `${name}: picking a colour collapses`);
    } else {
      await page.getByRole("button", { name: "Colour 3", exact: true }).click();
      expect((await page.locator(".toolbar .toolbar-row").count()) === 1, `${name}: picking a colour keeps one row`);
    }
    if (name === "phone") {
      await page.locator(".level-chip").click();
      await page.waitForTimeout(300);
      const list = await box(page, ".level-list");
      expect(inside(list, vp, 0), `phone: level list ${JSON.stringify(list)} inside the viewport`);
      await page.screenshot({ path: join(DIR, "phone-level-list.png") });
      await page.locator(".level-chip").click();
      const more = page.locator(".peer.more");
      if ((await more.count()) > 0) {
        await more.click();
        await page.waitForTimeout(300);
        const peers = await box(page, ".peer-list");
        expect(inside(peers, vp, 0), `phone: presence list ${JSON.stringify(peers)} inside the viewport`);
        await page.screenshot({ path: join(DIR, "phone-presence-list.png") });
        await more.click();
      } else expect(local, "phone: +N chip shown with six people on the board");
    }
    expect(await draw(page, options.hasTouch, vp), `${name}: pencil stroke shows on the canvas`);
    await page.screenshot({ path: join(DIR, `${name}-drawn.png`) });
    await context.close();
  }
} finally {
  for (const ctx of helpers) await ctx.close();
  await browser.close();
}
console.log(`console errors: ${errors.length}`);
for (const e of errors) console.log(`  ${e}`);
console.log(`screenshots: ${DIR}`);
if (failures.length > 0 || errors.length > 0) process.exit(1);
EOF
