import { CF_ENV, readEnvFile } from "../npm-scripts/env.mjs";
const sha = process.argv[2];
const env = readEnvFile(CF_ENV);
const token = env.CLOUDFLARE_API_TOKEN;
console.log(`env keys: ${Object.keys(env).join(",")}`);
const api = async (path) => {
  const r = await fetch(`https://api.cloudflare.com/client/v4${path}`, { headers: { Authorization: `Bearer ${token}` } });
  const j = await r.json();
  if (!j.success) throw new Error(`${path}: ${r.status} ${JSON.stringify(j.errors)}`);
  return j.result;
};
const account = env.CLOUDFLARE_ACCOUNT_ID ?? (await api("/accounts"))[0].id;
const scripts = await api(`/accounts/${account}/workers/scripts`);
const script = scripts.find((s) => s.id === "stallion");
const tag = script.tag;
const sleep = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
const deadline = Date.now() + 25 * 60_000;
while (Date.now() < deadline) {
  const builds = await api(`/accounts/${account}/builds/workers/${tag}/builds?per_page=10`);
  const list = Array.isArray(builds) ? builds : (builds.builds ?? []);
  const b = list.find((x) => x.build_trigger_metadata?.commit_hash === sha);
  console.log(new Date().toISOString(), b ? `${b.status} ${b.build_outcome ?? ""}` : "no build yet");
  if (b && b.status === "stopped") {
    console.log(`outcome ${b.build_outcome}`);
    process.exit(b.build_outcome === "success" ? 0 : 1);
  }
  sleep(30_000);
}
console.log("timed out");
process.exit(1);
EOF
